mapper.select:

where e.subject_id = #{subjectId}
  and (e.status is null or e.status = '0')
order by e.edge_id asc


where e.to_knowledge_id = #{toKnowledgeId}
  and (e.status is null or e.status = '0')
order by e.edge_id asc


where e.from_knowledge_id = #{fromKnowledgeId}
  and (e.status is null or e.status = '0')
order by e.edge_id asc


where e.from_knowledge_id = #{fromKnowledgeId}
  and e.to_knowledge_id = #{toKnowledgeId}
  and e.relation = #{relation}
limit 1
